pub const TEST_REGISTER_2: &str = "Contract-dependent budgets, workload durations, precision/tolerances and policies must be fixed before execution. Missing inputs prevent a valid outcome. Documentary investigations use versioned sources and an explicit review oracle. Model-check bounds and stress limits must remain visible.";
